<script lang="ts">
  // Native checkbox with its label, optional hint and error (aria-describedby, aria-invalid).
  import type { HTMLInputAttributes } from 'svelte/elements';
  import { t } from '../i18n/i18n.svelte';
  import { describedBy } from './helpers';

  interface Props extends Omit<
    HTMLInputAttributes,
    'type' | 'checked' | 'style' | 'children' | 'id' | 'aria-describedby' | 'aria-invalid'
  > {
    /** Visible label. */
    label: string;
    /** Bound state. */
    checked?: boolean;
    /** Element id (generated by default). */
    id?: string;
    /** Help text linked to the checkbox. */
    hint?: string;
    /** Error message; sets aria-invalid. */
    error?: string | undefined;
    /** The input element, for focus management. */
    element?: HTMLInputElement | undefined;
  }

  let {
    label,
    checked = $bindable(false),
    id,
    hint,
    error,
    element = $bindable(),
    class: className = '',
    ...rest
  }: Props = $props();

  const uid = $props.id();
  const inputId = $derived(id ?? `${uid}-checkbox`);
  const hintId = $derived(`${inputId}-hint`);
  const errorId = $derived(`${inputId}-error`);
  const invalid = $derived(error !== undefined && error !== '');
</script>

<div class="tt-check {className}">
  <div class="tt-check__row">
    <input
      {...rest}
      bind:this={element}
      bind:checked
      type="checkbox"
      id={inputId}
      class="tt-check__input"
      aria-invalid={invalid ? 'true' : undefined}
      aria-describedby={describedBy(hint && hintId, invalid && errorId)}
    />
    <label class="tt-check__label" for={inputId}>{label}</label>
  </div>
  {#if hint}
    <p class="tt-check__hint" id={hintId}>{hint}</p>
  {/if}
  {#if invalid}
    <p class="tt-check__error" id={errorId}>
      <span class="visually-hidden">{t('components.field.errorPrefix')}</span>
      {error}
    </p>
  {/if}
</div>

<style>
  .tt-check {
    margin-bottom: var(--tt-space-3);
  }

  .tt-check__row {
    display: flex;
    align-items: flex-start;
    gap: var(--tt-space-2);
  }

  .tt-check__input {
    flex: none;
    width: 1.25rem;
    height: 1.25rem;
    margin: 0.15rem 0 0;
    accent-color: var(--tt-primary);
  }

  .tt-check__hint,
  .tt-check__error {
    margin: var(--tt-space-1) 0 0 calc(1.25rem + var(--tt-space-2));
    font-size: var(--tt-font-size-sm);
  }

  .tt-check__hint {
    color: var(--tt-muted);
  }

  .tt-check__error {
    color: var(--tt-danger);
    font-weight: var(--tt-font-weight-bold);
  }
</style>
